{
  "cases": [
    {
      "id": "C1",
      "instrument_review": "The 70% score describes performance on the 100 grid puzzles in one run. Exact-grid scoring specifies the scoring rule, but puzzle selection and conditions for fair system comparisons are not detailed. Repeatability is unknown, and broader abilities are not assessed.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is neither documented nor explicitly ruled out."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score provides no evidence of consistency across runs."
        }
      ]
    },
    {
      "id": "C2",
      "instrument_review": "The score describes one evaluation of the grid puzzles using exact-grid scoring. The explicit lack of repeated runs leaves score consistency unassessed; it does not demonstrate instability. Puzzle selection and details needed to judge fair comparisons are not supplied.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly states that repeated testing did not occur."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Without repeated results, stability remains unknown."
        }
      ]
    },
    {
      "id": "C3",
      "instrument_review": "Repeated evaluations held the listed conditions constant and met the report's stated stability threshold. This supports consistency for this system and setup. Exact-grid scoring defines success, but puzzle selection, other systems, and broader uses remain unassessed.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The passage documents repeated testing under matching conditions."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The reported range meets the supplied stability definition."
        }
      ]
    },
    {
      "id": "C4",
      "instrument_review": "The repeated results document substantial inconsistency under the listed unchanged conditions. The single 70% result therefore gives an incomplete account of performance. Exact-grid scoring is specified, but the cause of variation and puzzle-selection details are missing.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under matching conditions is explicitly documented."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The reported spread exceeds the stated stability threshold."
        }
      ]
    },
    {
      "id": "C5",
      "instrument_review": "Installation instructions help users obtain and install the benchmark, but add no evidence about score consistency. The 70% result remains limited to one reported run on these puzzles. Puzzle selection and conditions needed to judge fair comparisons are not detailed.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation documentation does not establish that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no repeated-score evidence supporting stability."
        }
      ]
    },
    {
      "id": "C6",
      "instrument_review": "The reported counts support A's better performance on the evaluated grid puzzles, matching the intended use. Exact-grid scoring and fixed instructions aid comparison, but repeated-run consistency and matching resources or settings are not reported. Results on other domains are absent.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the stated conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The evidence does not establish a comparison of general intelligence across domains."
        }
      ]
    },
    {
      "id": "C7",
      "instrument_review": "A's higher puzzle count supports a comparison on the evaluated grid tasks. The intended selection for general intelligence across domains exceeds the supplied evidence. Fixed instructions and exact-grid scoring help define the comparison, but repeated-run consistency, other conditions, and cross-domain evidence are missing.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The reported results show better evaluated grid-puzzle performance for A."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Stating a broader intended use does not supply evidence for it."
        }
      ]
    },
    {
      "id": "C8",
      "instrument_review": "Initial test scores alone do not establish improved workshop decisions. The later preregistered, randomized trial with blinded correctness checks supports choosing A for decision correctness in the studied workshop; the reported difference interval favors A. Evidence from other workshops, repeated trials, time outcomes, and safety outcomes is absent.",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "No initial evidence links those scores to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%. The reported uncertainty interval for the difference was 12 to 28 percentage points.",
          "reason": "The randomized trial reports higher correctness with A and an interval favoring A, supporting the claim within the studied conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness findings do not establish an improvement in an unmeasured safety outcome."
        }
      ]
    }
  ],
  "closing_note": "No instructions were unclear. Missing evidence was treated as Not established; explicit conflicting evidence was treated as Contradicted."
}
